for s in data/enterprise/shifts/*; do echo "== $s"; node -e '
const r=JSON.parse(require("fs").readFileSync(process.argv[1]+"/result.json","utf8"));
const trim=(o,d=0)=>{ if(d>3) return "…"; if(Array.isArray(o)) return o.slice(0,4).map(x=>trim(x,d+1)); if(o&&typeof o==="object"){const r={}; for(const k of Object.keys(o)) r[k]=trim(o[k],d+1); return r;} if(typeof o==="string"&&o.length>200) return o.slice(0,200)+"…"; return o;};
console.log(JSON.stringify(trim(r),null,1).slice(0,5000));
' $s; ls $s/sessions | head; done

